# Make coding more python3-ish
from __future__ import (absolute_import, division, print_function)
__metaclass__ = type

import yaml

from ansible.module_utils.six import PY3, text_type, binary_type
from ansible.module_utils.common.yaml import SafeDumper
from ansible.parsing.yaml.objects import AnsibleUnicode, AnsibleSequence, AnsibleMapping, AnsibleVaultEncryptedUnicode
from ansible.utils.unsafe_proxy import AnsibleUnsafeText, AnsibleUnsafeBytes
from ansible.vars.hostvars import HostVars, HostVarsVars
from ansible.vars.manager import VarsWithSources


class AnsibleDumper(SafeDumper):
    '''
    A simple stub class that allows us to add representers
    for our overridden object types.
    '''


def represent_hostvars(self, data):
    return self.represent_dict(dict(data))


# Note: only want to represent the encrypted data
def represent_vault_encrypted_unicode(self, data):
    return self.represent_scalar(u'!vault', data._ciphertext.decode(), style='|')


if PY3:
    def represent_unicode(self, data):
        return yaml.representer.SafeRepresenter.represent_str(self, text_type(data))

    def represent_binary(self, data):
        return yaml.representer.SafeRepresenter.represent_binary(self, binary_type(data))
else:
    def represent_unicode(self, data):
        return yaml.representer.SafeRepresenter.represent_unicode(self, text_type(data))

    def represent_binary(self, data):
        return yaml.representer.SafeRepresenter.represent_str(self, binary_type(data))


AnsibleDumper.add_representer(
    AnsibleUnicode,
    represent_unicode,
)

AnsibleDumper.add_representer(
    AnsibleUnsafeText,
    represent_unicode,
)

AnsibleDumper.add_representer(
    AnsibleUnsafeBytes,
    represent_binary,
)

AnsibleDumper.add_representer(
    HostVars,
    represent_hostvars,
)

AnsibleDumper.add_representer(
    HostVarsVars,
    represent_hostvars,
)

AnsibleDumper.add_representer(
    VarsWithSources,
    represent_hostvars,
)

AnsibleDumper.add_representer(
    AnsibleSequence,
    yaml.representer.SafeRepresenter.represent_list,
)

AnsibleDumper.add_representer(
    AnsibleMapping,
    yaml.representer.SafeRepresenter.represent_dict,
)

AnsibleDumper.add_representer(
    AnsibleVaultEncryptedUnicode,
    represent_vault_encrypted_unicode,
)

    fail_on_undefined = self._fail_on_undefined_errors

has_template_overrides = data.startswith(JINJA2_OVERRIDE)

try:
    # NOTE Creating an overlay that lives only inside do_template means that overrides are not applied
    # when templating nested variables in AnsibleJ2Vars where Templar.environment is used, not the overlay.
    # This is historic behavior that is kept for backwards compatibility.
    if overrides:
        myenv = self.environment.overlay(overrides)
    elif has_template_overrides:
        myenv = self.environment.overlay()
    else:
        myenv = self.environment

    # Get jinja env overrides from template
    if has_template_overrides:
        eol = data.find('\n')
        line = data[len(JINJA2_OVERRIDE):eol]
        data = data[eol + 1:]
        for pair in line.split(','):
            (key, val) = pair.split(':')
            key = key.strip()
            setattr(myenv, key, ast.literal_eval(val.strip()))

    if escape_backslashes:
        # Allow users to specify backslashes in playbooks as "\\" instead of as "\\\\".
        data = _escape_backslashes(data, myenv)

    try:
        t = myenv.from_string(data)
    except TemplateSyntaxError as e:
        raise AnsibleError("template error while templating string: %s. String: %s" % (to_native(e), to_native(data)))
    except Exception as e:
        if 'recursion' in to_native(e):
            raise AnsibleError("recursive loop detected in template string: %s" % to_native(data))
        else:
            return data

    if disable_lookups:
        t.globals['query'] = t.globals['q'] = t.globals['lookup'] = self._fail_lookup

    jvars = AnsibleJ2Vars(self, t.globals)

    self.cur_context = new_context = t.new_context(jvars, shared=True)
    rf = t.root_render_func(new_context)

    try:
        if self.jinja2_native:
            res = ansible_native_concat(rf)
        else:
            res = j2_concat(rf)
        unsafe = getattr(new_context, 'unsafe', False)
        if unsafe:
            res = wrap_var(res)
    except TypeError as te:
        if 'AnsibleUndefined' in to_native(te):
            errmsg = "Unable to look up a name or access an attribute in template string (%s).\n" % to_native(data)
            errmsg += "Make sure your variable name does not contain invalid characters like '-': %s" % to_native(te)
            raise AnsibleUndefinedVariable(errmsg)
        else:
            display.debug("failing because of a type error, template data is: %s" % to_text(data))
            raise AnsibleError("Unexpected templating type error occurred on (%s): %s" % (to_native(data), to_native(te)))

    if self.jinja2_native and not isinstance(res, string_types):
        return res

    if preserve_trailing_newlines:
        # The low level calls above do not preserve the newline
        # characters at the end of the input data, so we use the
        # calculate the difference in newlines and append them
        # to the resulting output for parity
        #
        # jinja2 added a keep_trailing_newline option in 2.7 when
        # creating an Environment.  That would let us make this code
        # better (remove a single newline if
        # preserve_trailing_newlines is False).  Once we can depend on
        # that version being present, modify our code to set that when
        # initializing self.environment and remove a single trailing
        # newline here if preserve_newlines is False.
        res_newlines = _count_newlines_from_end(res)
        if data_newlines > res_newlines:
            res += self.environment.newline_sequence * (data_newlines - res_newlines)
            if unsafe:
                res = wrap_var(res)
    return res
except (UndefinedError, AnsibleUndefinedVariable) as e:
    if fail_on_undefined:
        raise AnsibleUndefinedVariable(e)
    else:
        display.debug("Ignoring undefined failure: %s" % to_text(e))
        return data
